#[test]
fn timeout_means_effect_unknown_read_back_and_no_retry() {
    let mut w = World::new();
    w.bus.with(2, |u| u.silent_writes = true);
    let audit = MemoryAudit::new();
    let mut svc = service(&w, &audit);
