fn minute_rollups_use_good_samples_only() {
    let mut h = hist();
    let mut rows = Vec::new();
    for i in 0..180i64 {
        let ts = T0 + i * 1000;
        let q = if (60..90).contains(&i) { Quality::Timeout } else { Quality::Good };
        rows.push(sample("temperature", i as u64, ts, q, q.is_good().then_some(20.0 + (i % 60) as f64 / 10.0)));
