//! Exports (PRD R21): CSV, XLSX, JSON. Every measurement row carries
//! quality, exception code, age and the profile ID + version. Times are
//! ISO-8601 UTC; decimals always use `.`. Text cells that start with
//! `= + - @`, tab or CR get a leading `'` (formula-injection guard).
//! Export types contain no credential fields at all.

pub mod csv;
pub mod json;
pub mod xlsx;

use crate::historian::{AuditRow, DeviceRow, EventRow, Historian, HistorianError, SessionInfo, StoredSample};
use serde::Serialize;

/// Escape a text cell for spreadsheets.
pub fn guard_text(s: &str) -> String {
    if s.starts_with(['=', '+', '-', '@', '\t', '\r']) { format!("'{s}") } else { s.to_owned() }
}

#[derive(Clone, Debug, PartialEq, Serialize)]
pub struct ExportDoc {
    pub generated_ms: i64,
    pub app_version: String,
    pub session: SessionInfo,
    pub devices: Vec<DeviceRow>,
    pub measurements: Vec<StoredSample>,
    pub events: Vec<EventRow>,
    pub commands: Vec<AuditRow>,
}

impl ExportDoc {
    pub fn from_historian(h: &Historian, session: &str, generated_ms: i64, app_version: &str) -> Result<Self, HistorianError> {
        let info = h
            .sessions()?
            .into_iter()
            .find(|s| s.id == session)
            .ok_or_else(|| HistorianError::Db(format!("unknown session '{session}'")))?;
        Ok(Self {
            generated_ms,
            app_version: app_version.to_owned(),
            devices: h.devices(session)?,
            measurements: h.samples(session, None, None, i64::MIN, i64::MAX)?,
            events: h.events(session)?,
            commands: h.audit(session)?,
            session: info,
        })
    }
}

/// Raw registers as compact hex words: `00FD 0138`.
pub fn raw_hex(regs: &[u16]) -> String {
    regs.iter().map(|r| format!("{r:04X}")).collect::<Vec<_>>().join(" ")
}

/// Shortest round-trip decimal with `.` (never locale-formatted).
pub fn number(v: f64) -> String {
    if v.is_finite() { format!("{v}") } else { String::new() }
}

pub const MEASUREMENT_COLUMNS: [&str; 15] = [
    "ts_utc",
    "ts_ms",
    "device_id",
    "tag_id",
    "value",
    "text",
    "unit",
    "quality",
    "exception_code",
    "age_ms",
    "value_ts_utc",
    "raw_hex",
    "seq",
    "profile_id",
    "profile_version",
];

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn formula_guard() {
        for s in ["=1+1", "+cmd", "-2", "@SUM(A1)", "\tx", "\rx"] {
            assert_eq!(guard_text(s), format!("'{s}"));
        }
        for s in ["soil", "", "25.3", " =x", "a=b"] {
            assert_eq!(guard_text(s), s);
        }
    }
}

//! CSV export of measurements (UTF-8, RFC 4180 quoting, `.` decimals).

use super::{ExportDoc, MEASUREMENT_COLUMNS, guard_text, number, raw_hex};
use crate::time::iso8601_utc_ms;

fn field(out: &mut String, s: &str) {
    if s.contains([',', '"', '\n', '\r']) {
        out.push('"');
        out.push_str(&s.replace('"', "\"\""));
        out.push('"');
    } else {
        out.push_str(s);
    }
}

fn row(out: &mut String, cells: &[String]) {
    for (i, c) in cells.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        field(out, c);
    }
    out.push_str("\r\n");
}

/// Measurements as CSV. Text columns pass through the formula guard; numeric columns are plain numbers.
pub fn measurements(doc: &ExportDoc) -> String {
    let mut out = String::new();
    row(&mut out, &MEASUREMENT_COLUMNS.map(String::from));
    for s in &doc.measurements {
        row(
            &mut out,
            &[
                iso8601_utc_ms(s.ts_ms),
                s.ts_ms.to_string(),
                guard_text(&s.device_id),
                guard_text(&s.tag_id),
                s.value.map(number).unwrap_or_default(),
                s.text.as_deref().map(guard_text).unwrap_or_default(),
                s.unit.as_deref().map(guard_text).unwrap_or_default(),
                s.quality.as_str().to_owned(),
                s.quality.exception_code().map(|c| format!("{c:02X}")).unwrap_or_default(),
                s.age_ms.map(|a| a.to_string()).unwrap_or_default(),
                s.value_ts_ms.map(iso8601_utc_ms).unwrap_or_default(),
                raw_hex(&s.raw),
                s.seq.to_string(),
                guard_text(&s.profile_id),
                guard_text(&s.profile_version),
            ],
        );
    }
    out
}

