        a.advance_to(0);
        for u in [3] {
            a.handle_pdu(u, &WriteRequest::SingleRegister { address: 5, value: 1 }.encode().unwrap(), 0);
        }
        let mut b = SimWorld::training(42);
        b.advance_to(0);
        b.handle_pdu(3, &WriteRequest::SingleRegister { address: 5, value: 1 }.encode().unwrap(), 0);
