                    assert_eq!(obs.quality, Quality::Good, "{file} {}: {:?}", p.registers[tag.register].id, obs.error);
                    seen += 1;
                }
            }
        }
        assert_eq!(seen, p.registers.len() * 4, "{file}");
        if p.simulated_only {
            assert_eq!(p.support_level, SupportLevel::Simulated, "simulator results never upgrade a profile");
        }
    }
}

#[test]
fn soil_profile_matches_the_documented_map() {
    let p = bundled("bgt-smps-8in1.json");
    assert_eq!(p.support_level, SupportLevel::Documented);
    let ids: Vec<(&str, u16, Option<f64>)> = p.registers.iter().map(|r| (r.id.as_str(), r.address, r.scale)).collect();
    assert_eq!(
        ids,
        vec![
            ("temperature", 0, Some(0.1)),
            ("moisture", 1, Some(0.1)),
            ("ec", 2, None),
            ("salinity", 3, None),
            ("nitrogen", 4, None),
            ("phosphorus", 5, None),
            ("potassium", 6, None),
            ("ph", 7, Some(0.01)),
        ]
    );
    let rtu = p.transport.rtu.unwrap();
    assert_eq!((rtu.unit_id, rtu.baud, rtu.data_bits, rtu.stop_bits), (1, 9600, 8, 1));
}

use buslink_core::poll::scheduler::{LinkScheduler, Step};
use buslink_core::quality::Sample;

/// Run the scheduler until the manual clock reaches `until_mono`, collecting samples.
pub fn run_until(sched: &mut LinkScheduler, t: &mut dyn Transport, clock: &ManualClock, until_mono: u64, out: &mut Vec<Sample>) -> Step {
    loop {
        if clock.mono_ms() >= until_mono {
            return Step::Worked;
        }
        match sched.step(t, &mut |s| out.push(s)) {
            Step::Worked => {}
            Step::LinkDown => return Step::LinkDown,
            Step::Idle { until_mono_ms } => clock.advance_to(until_mono_ms.min(until_mono)),
        }
    }
}

