#[test]
fn simulated_session_with_a_gap_is_logged_and_exported_honestly() {
    let mut w = SimWorld::training(4);
    w.add_fault(FaultRule { unit: 1, kind: FaultKind::Timeout, trigger: Trigger::Window { from_ms: 120_000, until_ms: 180_000 } }).unwrap();
    let (mut s, mut t, clock) = setup(w.shared(), &["bgt-smps-8in1.json", "sim-energy-meter.json"], 1000);
    let mut out = Vec::new();
    run_until(&mut s, &mut t, &clock, 300_000, &mut out);

    let mut h = Historian::open_in_memory().unwrap();
    h.begin_session("demo", UTC0, "0.1.0", "simulator", 1000).unwrap();
    for (id, pid, unit) in [("bgt-smps-8in1", "bgt.smps-8in1", 1), ("sim-energy-meter-basic", "sim.energy-meter-basic", 4)] {
        h.register_device(&DeviceRow {
            session: "demo".into(),
            device_id: id.into(),
            name: id.into(),
            profile_id: pid.into(),
            profile_version: "1.0.0".into(),
            unit_id: unit,
            link: "training".into(),
        })
        .unwrap();
    }
    let mut dec = LogDecimator::new(1000);
    let mut batch = SampleBatcher::new(1000, 500);
    for smp in out.into_iter().filter(|x| dec.keep(x)) {
        let now = smp.ts_ms;
        if let Some(b) = batch.push(smp, now) {
            h.insert_samples(&b).unwrap();
        }
    }
    h.insert_samples(&batch.flush()).unwrap();
    h.rollup_until(UTC0 + 300_000).unwrap();

    let temp = h.samples("demo", Some("bgt-smps-8in1"), Some("temperature"), 0, i64::MAX).unwrap();
    let gap: Vec<_> = temp.iter().filter(|x| (UTC0 + 120_000..UTC0 + 180_000).contains(&x.ts_ms)).collect();
    assert!(!gap.is_empty() && gap.iter().all(|x| x.value.is_none() && !x.quality.is_good()), "the gap is stored as a gap");
    assert!(gap.iter().any(|x| x.quality == Quality::Timeout));
    assert!(temp.iter().filter(|x| x.ts_ms > UTC0 + 200_000).all(|x| x.quality == Quality::Good));
    let minute2 = h.rollups("demo", "bgt-smps-8in1", "temperature", UTC0 + 120_000, UTC0 + 180_000).unwrap();
    assert!(minute2.is_empty(), "no rollup is made from TIMEOUT samples");
    assert_eq!(h.rollups("demo", "sim-energy-meter-basic", "voltage", UTC0, UTC0 + 300_000).unwrap().len(), 5);

    let doc = ExportDoc::from_historian(&h, "demo", UTC0 + 300_000, "0.1.0").unwrap();
    let csv = export::csv::measurements(&doc);
    assert!(csv.lines().any(|l| l.contains(",temperature,,") && l.contains(",TIMEOUT,")), "TIMEOUT rows with empty values");
    let xlsx = export::xlsx::workbook(&doc).unwrap();
    assert!(xlsx.len() > 1000);
    let json = export::json::document(&doc);
    assert!(json["measurements"].as_array().unwrap().iter().any(|m| m["quality"] == "TIMEOUT" && m["value"].is_null()));
}

