struct Bench {
    clock: Arc<ManualClock>,
    world: SharedWorld,
    t: SimTransport,
    ex: buslink_core::transport::exchange::Exchanger,
}

impl Bench {
    fn new() -> Self {
        let clock = ManualClock::shared(UTC0);
        let world = SimWorld::training(2026).shared();
        let t = SimTransport::rtu(world.clone(), clock.clone() as Arc<dyn Clock>, Chunking::Random { max: 5, seed: 1 });
        let ex = rtu_exchanger(&clock);
        Self { clock, world, t, ex }
    }
    fn link(&mut self) -> DirectLink<'_> {
        DirectLink { transport: &mut self.t, exchanger: &mut self.ex, timeout_ms: 500 }
    }
    fn hr(&mut self, unit: u8, a: u16) -> u16 {
        regs(read(&mut self.ex, &mut self.t, unit, ReadFunction::HoldingRegisters, a, 1).unwrap())[0]
    }
}

fn target(file: &str) -> CommandTarget {
    let link = sim_link("training");
    let (d, p) = device(file, &link, 1000);
    CommandTarget { device: d, link, profile: p }
}

fn run_cmd(svc: &mut CommandService, b: &mut Bench, req: CommandRequest) -> buslink_core::command::CommandOutcome {
    let p = svc.preview(&mut b.link(), req).unwrap();
    svc.confirm(p.id).unwrap();
    svc.execute(&mut b.link()).unwrap()
}

#[test]
fn vfd_set_frequency_run_stop_with_readback() {
    let mut b = Bench::new();
    let audit = MemoryAudit::new();
    let mut svc = CommandService::new(b.clock.clone() as Arc<dyn Clock>, Box::new(audit.clone()), "s", CommandConfig::default());
    svc.arm(target("sim-vfd.json"), Operator { user: "judge".into(), role: Role::Operator }).unwrap();
    let p = svc.preview(&mut b.link(), CommandRequest::Named { command: "set_frequency".into(), value: Some(30.0) }).unwrap();
    assert_eq!((p.old_value, p.new_value, p.raw_registers.clone()), (Some(0.0), 30.0, vec![3000]));
    assert!(p.frame_hex.starts_with("02 06 00 01 0B B8"));
    svc.confirm(p.id).unwrap();
    let o = svc.execute(&mut b.link()).unwrap();
    assert_eq!((o.ack, o.readback, o.readback_value), (Ack::Acknowledged, Readback::Verified, Some(30.0)));
    let o = run_cmd(&mut svc, &mut b, CommandRequest::Named { command: "run".into(), value: None });
    assert_eq!((o.ack, o.readback), (Ack::Acknowledged, Readback::Verified));
    assert!(b.hr(2, 3) < 3000, "acknowledged is not 'at speed' yet");
    b.clock.advance(8_000);
    assert_eq!(b.hr(2, 3), 3000, "process reached target (measured feedback)");
    assert_eq!(b.hr(2, 4) & 0b11, 0b11);
    let o = run_cmd(&mut svc, &mut b, CommandRequest::Named { command: "stop".into(), value: None });
    assert_eq!(o.readback, Readback::Verified);
    b.clock.advance(8_000);
    assert_eq!(b.hr(2, 3), 0);
    assert!(audit.records().len() >= 13, "arm + 3 × (preview, confirm, sent, result)");
}

#[test]
fn vfd_fault_run_is_acknowledged_but_not_running() {
    let mut b = Bench::new();
    b.world.lock().unwrap().with_model::<Vfd, ()>(2, |v| v.trip(FAULT_OVERCURRENT)).unwrap();
    let mut svc = CommandService::new(b.clock.clone() as Arc<dyn Clock>, Box::new(MemoryAudit::new()), "s", CommandConfig::default());
    svc.arm(target("sim-vfd.json"), Operator { user: "judge".into(), role: Role::Operator }).unwrap();
    run_cmd(&mut svc, &mut b, CommandRequest::Named { command: "set_frequency".into(), value: Some(20.0) });
    let o = run_cmd(&mut svc, &mut b, CommandRequest::Named { command: "run".into(), value: None });
    assert_eq!((o.ack, o.readback), (Ack::Acknowledged, Readback::Verified), "the control word reads back 1");
    b.clock.advance(5_000);
    assert_eq!(b.hr(2, 4), 1 << 3, "status: fault, not running");
    assert_eq!(b.hr(2, 3), 0);
    // Reset is refused by the drive only in the sense that it needs a stop first.
    run_cmd(&mut svc, &mut b, CommandRequest::Named { command: "stop".into(), value: None });
    let o = run_cmd(&mut svc, &mut b, CommandRequest::Named { command: "reset_fault".into(), value: None });
    assert_eq!((o.readback, o.readback_value), (Readback::Verified, Some(0.0)), "fault code read back as 0");
}

#[test]
